	m.data = make(map[string]*model.Album)
	m.all = albums
	for i, a := range m.all {
		m.data[a.ID] = &m.all[i]
	}
}

func (m *MockAlbumRepo) Exists(id string) (bool, error) {
	if m.err {
		return false, errors.New("Error!")
	}
	_, found := m.data[id]
	return found, nil
}

